mapper.select:
SELECT to_user_id AS related_user_id, created_at
FROM following
WHERE from_user_id=#{fromUserId} AND rel_status=1

    AND (
        created_at < #{cursorCreatedAt}
        OR (created_at = #{cursorCreatedAt} AND to_user_id < #{cursorRelatedUserId})
    )

ORDER BY created_at DESC, to_user_id DESC
LIMIT #{limit}

SELECT from_user_id AS related_user_id, created_at
FROM follower
WHERE to_user_id=#{toUserId} AND rel_status=1

    AND (
        created_at < #{cursorCreatedAt}
        OR (created_at = #{cursorCreatedAt} AND from_user_id < #{cursorRelatedUserId})
    )

ORDER BY created_at DESC, from_user_id DESC
LIMIT #{limit}

SELECT id, from_user_id, to_user_id
FROM following

    WHERE id > #{afterId}

ORDER BY id ASC
LIMIT #{limit}
